import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.CWWEQfK7.js";const u=JSON.parse('{"title":"Add a setting: choose the owner and the loading path","description":"Decide whether a new setting belongs to Core, API, Worker, or MCP, then implement its default, validation, runtime behavior, and tests.","frontmatter":{"page_id":"development-configuration","title":"Add a setting: choose the owner and the loading path","description":"Decide whether a new setting belongs to Core, API, Worker, or MCP, then implement its default, validation, runtime behavior, and tests."},"headers":[],"relativePath":"en/development/configuration.md","filePath":"en/development/configuration.md","lastUpdated":1786627803000}'),n={name:"en/development/configuration.md"};function o(r,e,d,l,c,h){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="add-a-setting-choose-the-owner-and-the-loading-path" tabindex="-1">Add a setting: choose the owner and the loading path <a class="header-anchor" href="#add-a-setting-choose-the-owner-and-the-loading-path" aria-label="Permalink to &quot;Add a setting: choose the owner and the loading path&quot;">​</a></h1><p>Start a new setting by deciding ownership and activation. A setting in the wrong module creates a reverse dependency. A runtime setting that is registered but read through the base getter can appear successfully in administration while changing no real behavior.</p><h2 id="choose-the-owning-module-first" tabindex="-1">Choose the owning module first <a class="header-anchor" href="#choose-the-owning-module-first" aria-label="Permalink to &quot;Choose the owning module first&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Configuration purpose</th><th>Owner</th><th>Current examples</th></tr></thead><tbody><tr><td>Database, Milvus, repository, and security foundations shared by backend modules</td><td>Core <code>Settings</code></td><td><code>DATABASE_URL</code>, <code>REPOSITORY_STORAGE_PATH</code>, <code>ENCRYPTION_KEY</code></td></tr><tr><td>HTTP, browser Cookies, login rate limiting, access tokens, and API polling</td><td>API <code>ApiSettings</code></td><td><code>REDIS_URL</code>, <code>CORS_ORIGINS</code>, <code>POLLER_INTERVAL_SECONDS</code></td></tr><tr><td>Analysis queue, concurrency, LSP, dependency preparation, and user-question policy</td><td>Worker <code>WorkerSettings</code></td><td><code>MAX_PARALLEL_REPOSITORY_RUNS</code>, <code>REPOSITORY_LSP_ENABLED</code></td></tr><tr><td>MCP listening, origin, host, and build identity</td><td>MCP <code>McpSettings</code></td><td><code>MCP_ALLOWED_HOSTS</code>, <code>MCP_BUILD_COMMIT</code></td></tr><tr><td>Frontend build address and browser behavior</td><td>Frontend build configuration</td><td>API base address and frontend build options</td></tr></tbody></table><p>Core must not become the owner of every setting merely because the other modules can import it. It explicitly does not own Redis, Cookies, access tokens, Worker analysis policy, or MCP output behavior. API must not depend on Worker or MCP source.</p><p>The Worker administration contract is a deliberate boundary. Its 37 definitions live in Core <code>worker_runtime_contract.py</code> so API can display and validate them, while the fields and behavior remain in Worker. Sharing the contract does not move Worker behavior into Core.</p><h2 id="decide-whether-runtime-override-is-appropriate" tabindex="-1">Decide whether runtime override is appropriate <a class="header-anchor" href="#decide-whether-runtime-override-is-appropriate" aria-label="Permalink to &quot;Decide whether runtime override is appropriate&quot;">​</a></h2><p>A setting is a good runtime candidate only when:</p><ul><li>the change affects later operations and does not rebuild a database connection, HTTP listener, or encryption identity;</li><li>multiple instances can adopt it over a short refresh window;</li><li>a precise type, range, and activation note remove ambiguity;</li><li>returning to the environment value needs only deletion of the database override, not migration of existing data.</li></ul><p>Secrets, database and Redis addresses, Cookie names, listening addresses, and production identities should remain startup settings. The API process currently has 11 runtime-overridable settings; the other 37 shown by system administration are consumed by Worker.</p><h2 id="follow-the-current-loading-path" tabindex="-1">Follow the current loading path <a class="header-anchor" href="#follow-the-current-loading-path" aria-label="Permalink to &quot;Follow the current loading path&quot;">​</a></h2><ol><li>Core <code>Settings</code> declares shared fields and reads defaults, <code>.env</code>, and the process environment.</li><li>API, Worker, and MCP subclasses add module-owned fields.</li><li><code>get_settings()</code>, <code>get_api_settings()</code>, and their peers cache the settings object inside the process.</li><li>Each service runs its own validation during startup.</li><li>API or Worker reads registered <code>runtime.&lt;name&gt;</code> rows from <code>SystemSetting</code>, validates them, and places them in the process override map.</li><li>Business logic calls <code>get_effective_settings()</code> or <code>get_effective_api_settings()</code> to combine startup values with runtime overrides.</li></ol><p>Step 6 is essential. Code that keeps calling the cached base getter will ignore a database override even after it has been saved and refreshed.</p><h2 id="add-a-startup-setting" tabindex="-1">Add a startup setting <a class="header-anchor" href="#add-a-startup-setting" aria-label="Permalink to &quot;Add a startup setting&quot;">​</a></h2><p>For a module-local setting that takes effect after restart:</p><ol><li>Add a typed field with a conservative default to the settings class that owns the behavior.</li><li>Express ranges in Pydantic field constraints or the module validation function instead of scattering checks among callers.</li><li>Document format and purpose in the matching <code>.env.example</code>, without real secrets.</li><li>Read it through the module&#39;s cached settings entry point; do not import another service&#39;s settings class across repositories.</li><li>Test the default, a valid environment value, invalid values, and production constraints.</li><li>State which process must restart after a change.</li></ol><p>An API field belongs in <code>ApiSettings</code>, not Core merely to reuse an existing base class. The same rule applies to Worker and MCP.</p><h2 id="add-a-runtime-overridable-setting" tabindex="-1">Add a runtime-overridable setting <a class="header-anchor" href="#add-a-runtime-overridable-setting" aria-label="Permalink to &quot;Add a runtime-overridable setting&quot;">​</a></h2><p>In addition to the settings-class field, complete the entire path:</p><ol><li>Add a <code>RuntimeSettingDefinition</code> to the owning definition tuple.</li><li>Give it a stable internal <code>name</code>, uppercase <code>env_name</code>, administration group, value type, and <code>runtime_note</code>.</li><li>Set integer bounds or an explicit unlimited value; list every enum option.</li><li>Include that definition group in the service refresh function.</li><li>Make the real consumer call the effective settings getter.</li><li>If it must appear in API administration, ensure the definition reaches <code>MANAGED_RUNTIME_SETTING_DEFINITIONS</code>.</li><li>Test the environment value, database override, reset, invalid input, and activation timing.</li></ol><p>Runtime definitions currently support booleans, integers, strings, string lists, string maps, and enums. Generic validation also:</p><ul><li>rejects a Boolean used as an integer;</li><li>trims strings and rejects empty or longer-than-255-character values;</li><li>removes empty list items and limits a list to 50 entries;</li><li>lowercases and sorts map keys, with at most 50 entries;</li><li>lowercases enum input before matching the allowed options.</li></ul><h3 id="api-owned-runtime-settings" tabindex="-1">API-owned runtime settings <a class="header-anchor" href="#api-owned-runtime-settings" aria-label="Permalink to &quot;API-owned runtime settings&quot;">​</a></h3><p>Define them in <code>API_RUNTIME_SETTING_DEFINITIONS</code> and include them in <code>ALL_API_RUNTIME_SETTING_DEFINITIONS</code>. API refresh and system administration already use this union. Consumers must call <code>get_effective_api_settings()</code>.</p><h3 id="core-owned-runtime-settings" tabindex="-1">Core-owned runtime settings <a class="header-anchor" href="#core-owned-runtime-settings" aria-label="Permalink to &quot;Core-owned runtime settings&quot;">​</a></h3><p>Define them in <code>CORE_RUNTIME_SETTING_DEFINITIONS</code>. Both API and Worker read this shared group, so inspect consumer sites and tests in both services.</p><h3 id="worker-owned-runtime-settings" tabindex="-1">Worker-owned runtime settings <a class="header-anchor" href="#worker-owned-runtime-settings" aria-label="Permalink to &quot;Worker-owned runtime settings&quot;">​</a></h3><p>Put defaults and the administration contract in Core <code>worker_runtime_contract.py</code>, and the matching fields in Worker <code>WorkerSettings</code>. API only stores and reports the definitions. Worker refreshes them and reads them through <code>get_effective_settings()</code>.</p><h2 id="do-not-move-model-channels-back-into-environment-variables" tabindex="-1">Do not move model channels back into environment variables <a class="header-anchor" href="#do-not-move-model-channels-back-into-environment-variables" aria-label="Permalink to &quot;Do not move model channels back into environment variables&quot;">​</a></h2><p>Model providers, addresses, keys, model catalogs, and purposes are managed by API and stored in the database. The current <code>.env.example</code> explicitly says that model channels are configured through administration. Extend the model-channel schema and permission flow for new model capabilities instead of adding old-style global model environment variables.</p><h2 id="what-to-test" tabindex="-1">What to test <a class="header-anchor" href="#what-to-test" aria-label="Permalink to &quot;What to test&quot;">​</a></h2><p>Cover at least:</p><ul><li>settings creation from defaults and valid environment values;</li><li>rejection of wrong types, out-of-range values, and dangerous production combinations;</li><li>a database override reports <code>source: database</code>, and reset returns to <code>source: environment</code>;</li><li>a periodic refresh continues to a later cycle after one failure;</li><li>the business consumer actually uses the effective getter;</li><li>Worker contract defaults stay aligned with Worker settings fields;</li><li>security settings such as secrets or host allowlists have rejection tests.</li></ul><p>The closest API tests are <code>tests/test_runtime_settings_boundaries.py</code> and <code>tests/test_system_settings.py</code>. Core shared-setting coverage starts in <code>tests/test_core_settings.py</code> and the runtime-setting tests.</p><h2 id="checks-to-run" tabindex="-1">Checks to run <a class="header-anchor" href="#checks-to-run" aria-label="Permalink to &quot;Checks to run&quot;">​</a></h2><p>Use the repository&#39;s required UV commands in every affected module:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wheel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Run these checks before committing. If a shared contract changes, run tests and builds in each affected API, MCP, or Worker repository.</p><h2 id="completion-criteria" tabindex="-1">Completion criteria <a class="header-anchor" href="#completion-criteria" aria-label="Permalink to &quot;Completion criteria&quot;">​</a></h2><ul><li>The field is in the module that owns the behavior, without a new reverse dependency.</li><li>Environment name, type, default, range, and production constraint have tests.</li><li>A startup setting states its restart requirement; a runtime setting states which later operations it affects.</li><li>The value, source, and reset behavior shown by administration match the real consumer.</li><li><code>.env.example</code>, types, tests, and documentation use the same name and meaning.</li><li>Consumer repositories declare the correct minimum and upper Core bounds, then regenerate their lock files.</li></ul><h2 id="source-locations" tabindex="-1">Source locations <a class="header-anchor" href="#source-locations" aria-label="Permalink to &quot;Source locations&quot;">​</a></h2><ul><li><code>core/src/ershu/core/config.py</code>: shared settings and security validation.</li><li><code>core/src/ershu/services/runtime_settings.py</code>: runtime definitions, generic validation, refresh, and effective Core settings.</li><li><code>core/src/ershu/services/worker_runtime_contract.py</code>: Worker defaults and administration contract.</li><li><code>api/src/ershu/api/runtime_settings.py</code>: API settings, validation, and effective API settings.</li><li><code>api/src/ershu/api/services/system_settings.py</code>: administrator-visible definitions, database writes, and resets.</li><li><code>api/src/ershu/api_main.py</code>: API startup validation and periodic refresh.</li><li><code>worker/src/ershu/workers/runtime_settings.py</code>: Worker fields, validation, and effective settings.</li><li><code>mcp/src/ershu/mcp/runtime_settings.py</code>: MCP fields and production validation.</li><li><code>api/tests/test_runtime_settings_boundaries.py</code> and <code>api/tests/test_system_settings.py</code>: API setting-boundary tests.</li></ul>`,42)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
